return ['domain'=>'page-builder-sandwich','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'sw','project-id-version'=>'page-builder-sandwich','pot-creation-date'=>'2026-09-26T07:20:41+00:00','po-revision-date'=>'2026-09-26T07:20:41+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Page Builder Sandwich'=>'Page Builder Sandwich','https://zinndigital.com/wordpress-plugins/page-builder-sandwich'=>'https://zinndigital.com/wordpress-plugins/page-builder-sandwich','The foundation release of the rebuilt Page Builder Sandwich: a settings and About screen, a footprint-free front-end output layer, and one sample content block.'=>'Toleo la msingi la Page Builder Sandwich iliyojengwa upya: skrini ya mipangilio na Kuhusu, safu ya pato la mbele isiyo na alama za SEO, na kizuizi kimoja cha maudhui ya sampuli.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','AI providers'=>'Watoa huduma wa AI','The makers of ChatGPT. A good all-rounder.'=>'Watayarishaji wa ChatGPT. Mtu mzuri wa pande zote.','The makers of Claude. Strong at writing and careful reasoning.'=>'Waundaji wa Claude. Wenye nguvu katika uandចaji na werevu katika hoja.','Google\'s Gemini models. Fast and inexpensive.'=>'Miundo ya Gemini ya Google. Ina kasi na ni ya bei nafuu.','A European AI company with fast, inexpensive models.'=>'Kampuni ya Ulaya ya AI yenye miundo ya haraka na ya bei nafuu.','Low-cost models that are good at writing and code.'=>'Mitindo ya bei ya chini ambayo ni nzuri katika uandishi na msimbo.','One key for models from many different providers.'=>'Ufunguo mmoja kwa ajili ya miundo kutoka kwa watoa huduma wengi tofauti.','Any service that works like OpenAI\'s API, including a model running on your own computer or server.'=>'Huduma yoyote inayofanya kazi kama API ya OpenAI, ikiwa ni pamoja na mf modelu unaoendesha kwenye kompyuta au seva yako mwenyewe.','General (used when nothing more specific is set)'=>'Jumla (inatum ఏమి hakuna kitu mahususi zaidi kilichowekwa)','Writing and rewriting'=>'Kuandika na kuandika upya','Translation'=>'Tafsiri','Code and CSS'=>'Nambari ya siri na CSS','Sorry, you are not allowed to access this page.'=>'Samahani, huruhusiwi kufikia ukurasa huu.','These settings are shared by every plugin that uses them: %s.'=>'Mipangilio hii inashirikiwa na kila programu-jalizi inayozitumia: %s.','Your keys are encrypted in this site\'s database and are only ever sent to the provider you chose — never to us.'=>'Funguo zako zimesimbwa kwa njia fiche katika hifadhidata ya tovuti hii na hutumwa tu kwa mtoa huduma uliyemchagua — hazitumwi kwetu kamwe.','Step 1 of 2: choose an AI provider'=>'Hatua ya 1 kati ya 2: chagua mtoa huduma wa AI','You bring your own key, so you pay the provider directly for what you use. Not sure? Any of these works well; you can add more later.'=>'Unaleta ufunguo wako mwenyewe, kwa hiyo unamlipa mtoa huduma moja kwa moja kwa kile unachotumia. Hujaandikisha? Yoyote kati ya hizi inafanya vizuri; unaweza kuongeza nyingine baadaye.','Next'=>'Wafuatao','Step 2 of 2: connect %s'=>'Hatua ya 2 kati ya 2: unganisha %s','Enter the address of your OpenAI-compatible service, ending in /v1. A key is only needed if the service asks for one.'=>'Weka anwani ya huduma yako inayolingana na OpenAI, inayomalizika kwa /v1. Ufunguo unahitajika tu ikiwa huduma inaomba mmoja.','Open %s and sign in (or create a free account).'=>'Fungua %s na uingie (au ufungue akaunti ya bure).','the %s API keys page'=>'ukurasa wa funguo za API za %s','Create a new key and copy it.'=>'Unda ufunguo mpya na uunakili.','Paste it below and press "Save and test". We send one tiny request to check it works.'=>'Bandika hapa chini kisha bonyeza "Hifadhi na ujaribu". Tunatuma ombi moja dogo ili kuangalia kuwa linafanya kazi.','Most providers need a little credit on the account before a key works: %s.'=>'Watoa huduma wengi wanahitaji mkopo kidogo kwenye akaunti kabla ya ufunguo kufanya kazi: %s.','add credit'=>'ongeza mkopo','← Choose a different provider'=>'← Chagua mtoa huduma mwingine','Address'=>'Anwani','Saved key ends in …%s — paste a new one to replace it'=>'Ufunguo uliosekana unaishia kwenye …%s — bandika mpya ili kuubadilisha','Key (optional)'=>'Ufunguo (si lazima)','API key'=>'Ufunguo wa API','Save and test'=>'Hifadhi na ujaribu','Providers'=>'Watoa Huduma','Provider'=>'Mtoa huduma','Status'=>'Hali','Key'=>'Ufunguo','Get a key'=>'Pata ufunguo','Test'=>'Jaribu','Remove'=>'Ondoa','Saved by a newer plugin version: update this plugin, or enter the key again.'=>'Imesitishwa kwa toleo jipya zaidi la programu jalizi: sasisha programu jalizi hii, au uweke ufunguo tena.','The saved key can no longer be opened (the site\'s security keys changed). Enter it again.'=>'Ufunguo uliOhifadhiwa hauwezi kufunguliwa tena (funguo za usalama za tovuti zilibadilika). Ingiza tena.','Not connected'=>'Haijaunganishwa','Connected — last test passed %s'=>'Imeunganishwa — jaribio la mwisho limefaulu %s','Last test failed: %s'=>'Jaribio la mwisho limeshindwa: %s','Connected — not tested yet'=>'Imeunganishwa — haijajaribiwa bado','Which model to use'=>'Mtindo gani wa kutumia','★ marks our recommendation for that task. The list includes every model your key can use, read live from the provider.'=>'★ inaashiria pendekezo letu kwa kazi hiyo. Orodha hiyo inajumuisha kila modeli ambayo ufunguo wako unaweza kutumia, iliyosomwa moja kwa moja kutoka kwa mtoa huduma.','— Recommended for the provider —'=>'— Inapendekezwa kwa mtoa huduma —','Save models'=>'Hifadhi miundo','Refresh the model lists from the providers'=>'Sasisha orodha za miundo kutoka kwa watoa huduma','best quality'=>'ubora bora','lowest cost'=>'gharama ya chini kabisa','fastest'=>'haraka zaidi','Add a model yourself'=>'Ongeza mfano wewe mwenyewe','A model came out today? Paste its exact name to use it straight away.'=>'Modeli imetoka leo? Bandika jina lake kamili ili uitumie mara moja.','Model name'=>'Jina la mfano','Add model'=>'Ongeza mfano','Recommended models list'=>'Orodha ya miundo inayopendekezwa','The recommended models list could not be verified, so no recommendations are shown. Reinstall the plugin, or turn on daily updates below.'=>'Orodha ya mifumo inayopendekezwa haikuweza kuthibitishwa, kwa hiyo hakuna mapendekezo yanayoonyeshwa. Sakinisha tena programu-jalizi hiyo, au uwashe sasisho za kila siku hapa chini.','The list in use was published on %s. Each plugin update brings a fresh one.'=>'Orodha inayotumika ilichapishwa mnamo %s. Kila sasisho la programu-jalizi huleta mpya.','Also check Zinn Digital® once a day for an updated list.'=>'Pia angalia Zinn Digital® mara moja kwa siku kwa orodha iliyosasishwa.','Only a plain download request is sent: no key, no site address, nothing about your content. The list is signed, and a list that fails the signature check is ignored.'=>'Ombi la upakuaji wa kawaida pekee ndilo linalotumwa: hakuna ufunguo, hakuna anwani ya tovuti, hakuna kitu kuhusu maudhui yako. Orodha hiyo imetiwa sahihi, na orodha inayoshindwa ukaguzi wa sahihi hupuuzwa.','Last checked %1$s: %2$s.'=>'Mara ya mwisho kukaguliwa %1$s: %2$s.','Save, and check now if turned on'=>'Hifadhi, kisha uangalie sasa ikiwa imewashwa','a newer list was installed'=>'orododha mpya zaidi imewekwa','already up to date'=>'imesasasishwa kabisa','the download failed the signature check and was ignored'=>'upakuaji umeshindwa ukaguzi wa sahihi na umepuuzwa','Zinn Digital® could not be reached; the current list stays in use'=>'Zinn Digital® haikuwezi kufikiwa; orodha ya sasa inabaki ikitumika','turned off'=>'imezimwa','Open'=>'Fungua','Check their status page'=>'Angalia ukurasa wao wa hali','Open your billing page'=>'Fungua ukurasa wako wa malipo','Open your API keys page'=>'Fungua ukurasa wako wa funguo za API','Open the AI settings'=>'Fungua mipangilio ya AI','Sorry, you are not allowed to do that.'=>'Samahani, huruhusiwi kufanya hivyo.','Unknown provider.'=>'Mtoa huduma hajulikani.','Enter the address of your service, for example http://localhost:11434/v1.'=>'Weka anwani ya huduma yako, kwa mfano http://localhost:11434/v1.','That does not look like an API key. Copy it again, without spaces.'=>'Hiyo haionekani kama ufunguo wa API. Nakili tena, bila nafasi.','Paste your API key first.'=>'Bandika ufunguo wako wa API kwanza.','Key removed.'=>'Ufunguo umeondolewa.','Models saved.'=>'Mitindo imehifadhiwa.','Enter the model\'s exact name, for example as the provider\'s documentation writes it.'=>'Weka jina kamili la mtindo, kwa mfano jinsi lilivyoandikwa kwenye nyaraka za mtoa huduma.','Added %s. Choose it under "Which model to use".'=>'Imeongezwa %s. Ichague chini ya "Which model to use".','Model removed.'=>'Mtindo umeondolewa.','Daily updates are off. The list that came with the plugin is used.'=>'Sasisho za kila siku zimezimwa. Orodha iliyokuja na programu-jalizi inatumika.','Checked: %s.'=>'Imetejewa: %s.','Model lists refreshed.'=>'Orodha za miundo zimesasishwa.','Your AI key was saved by a newer version of one of your plugins. Update this plugin, or enter the key again in the AI settings.'=>'Ufunguo wako wa AI umehifadhiwa na toleo jipya zaidi la moja ya programu-jalizi zako. Sasisha programu-jalizi hii, au weka ufunguo tena katika mipangilio ya AI.','Your saved AI key can no longer be opened (the site\'s security keys changed). Enter it again in the AI settings.'=>'Ufunguo wako wa AI uliohifadhiwa hauwezi kufunguliwa tena (funguo za usalama za tovuti zimebadilika). Ingiza tena katika mipangilio ya AI.','AI is not set up yet. Add a key for an AI provider in the AI settings.'=>'AI bado haijasakinishwa. Ongeza ufunguo wa mtoa huduma wa AI katika mipangilio ya AI.','No model is chosen for this task. Pick one in the AI settings.'=>'Hakuna mtindo ulioteuliwa kwa kazi hii. Chagua mmoja katika mipangilio ya AI.','That AI provider is not supported by this version of the plugin.'=>'Mtoa huduma huyo wa AI haungwi mkono na toleo hili la programu-jalizi.','This site could not reach your AI service. Check that it is running and that its address is reachable from your web server (a service on your own computer is not reachable from a hosted site).'=>'Tovuti hii haikuweza kufikia huduma yako ya AI. Hakikisha kuwa inafanya kazi na kwamba anwani yake inafikika kutoka kwa seva yako ya mtandao (huduma kwenye kompyuta yako mwenyewe haifikiki kutoka kwa tovuti inayopangishwa).','This site could not reach %s. Check their status page; if they are up, your host may be blocking outgoing connections, or the address is wrong.'=>'Tovuti hii haikuweza kufikia %s. Angalia ukurasa wao wa hali; ikiwa iko hewani, mwenyeji wako anaweza kuwa anazuia miunganisho ya nje, au anwani si sahihi.','%s says your account has no credit or quota left. Add credit or raise your limit in your account with them, then try again.'=>'%s inasema akaunti yako haina salio au kiasi kilichobaki. Ongeza salio au ongeza kikomo chako katika akaunti yako nao, kisha jaribu tena.','%s did not accept your key. It may be mistyped, revoked or expired. Create a new key and paste it here.'=>'%s haikukubali ufunguo wako. Huenda umekosewa kuandikwa, umebatilishwa, au muda wake umekwisha. Unda ufunguo mpya na ubandike hapa.','%s refused this request for your key. The key may not have access to this model or feature, or your account needs verifying.'=>'%s imekataa ombi hili kwa ufunguo wako. Ufunguo huenda hauna ufikiaji wa mfano au kipengele hiki, atau akaunti yako inahitaji uthibitishaji.','The model "%1$s" is not available from %2$s for your key. Choose another model in the AI settings.'=>'Modeli "%1$s" haipatikani kutoka kwa %2$s kwa ufunguo wako. Chagua modeli nyingine katika mipangilio ya AI.','%s is limiting how fast your key can send requests. Wait a minute and try again, or raise your rate limit with them.'=>'%s inapunguza kasi ya ufunguo wako kutuma maombi. Subiri dakika moja kisha ujaribu tena, au ongeza kiwango chako cha kikomo nao.','%s is having problems right now (an outage or overload on their side). Nothing is wrong with your settings. Try again shortly.'=>'%s inapata shida kwa sasa (kukatika au mzigo mkubwa kwao). Hakuna tatizo na mipangilio yako. Jaribu tena hivi karibuni.','The AI request failed for a reason we could not identify. Try again; if it keeps happening, contact support with the details below.'=>'Ombi la AI limeshindwa kwa sababu hatikuweza kuitambua. Jaribu tena; likiendelea kutokea, wasiliana na huduma kwa wateja ukitumia maelezo yaliyo hapa chini.','The AI provider answered in a form this plugin could not read. Try again; if it keeps happening, choose another model or contact support.'=>'Mtoa huduma wa AI amejibu kwa mfumo ambao programu-jalishi hii haikuweza kuusoma. Jaribu tena; ikiwa itaendelea kutokea, chagua mtindo mwingine au uwasiliane na usaidizi.','Custom (OpenAI-compatible)'=>'Maalum (Inayooana na OpenAI)','Save a key for this provider first.'=>'Hifadhi ufunguo wa mtoa huduma huyu kwanza.','Your key works, but the provider lists no text model for it. Add a model yourself below.'=>'Ufunguo wako unafanya kazi, lakini mtoa huduma haorodheti mtindo wowote wa maandishi kwa ajili yake. Ongeza mtindo wewe mwenyewe hapa chini.','Connected. %1$s answered using %2$s. Your AI features are ready to use.'=>'Imeunganishwa. %1$s amejibu kwa kutumia %2$s. Vipengele vyako vya AI viko tayari kutumika.','Your user role is not allowed to use AI on this site. Ask an administrator.'=>'Jukumu lako la mtumiaji haliruhusiwi kutumia AI kwenye tovuti hii. Muombe msimamizi.','This site has reached its monthly AI spending limit. An administrator can raise it in the AI settings.'=>'Tovuti hii imefikia kikomo chake cha matumizi ya AI ya kila mwezi. Msimamizi anaweza kukiinua katika mipangilio ya AI.','This site has reached its monthly limit of AI requests. An administrator can raise it in the AI settings.'=>'Tovuti hii imefikia kikomo chake cha kila mwezi cha maombi ya AI. Msimamizi anaweza kukiongeza katika mipangilio ya AI.','Usage and cost'=>'Matumizi na gharama','The log, limits and role permissions apply to AI used through: %s.'=>'Magogo, vikomo na ruhusa za nafasi zinatumika kwa AI inayotumitika kupitia: %s.','Costs are approximate, worked out from published prices; a model with no known price counts as zero.'=>'Gharama ni za makadirio, zimehesabiwa kutoka kwa bei zilizochapishwa; mtindo usio na bei inayojulikana huhesabiwa kuwa sufuri.','This month: %1$s requests, about %2$s.'=>'Mwezi huu: maombi %1$s, takriban %2$s.','When'=>'Wakati','Who'=>'Nani','Used for'=>'Inatumika kwa','Model'=>'Aina','Tokens in / out'=>'Tokeni zinazoingia / zinazotoka','About'=>'Kuhusu','Result'=>'Matokeo','No AI requests have been made yet.'=>'Hakuna maombi ya AI yaliyofanywa bado.','Done'=>'Imekamilika','Limits and permissions'=>'Vikomo na ruhusa','Monthly spending limit (US dollars)'=>'Kikomo cha matumizi ya kila mwezi (dola za US)','Leave empty for no limit. AI stops for the rest of the month once the approximate cost reaches it.'=>'Acha wazi kiasi cha juu kikiwa hakina kikomo. AI husimama kwa mwezi uliobaki mara tu gharama inayokadiriwa inapofikia kiwango hicho.','Monthly request limit'=>'Kikomo cha maombi ya kila mwezi','Leave empty for no limit.'=>'Acha wazi bila kikomo.','Who may use AI'=>'Nani anayeweza kutumia AI','Tick none to let everyone who can use the plugin\'s features use AI. Administrators can always use it.'=>'Weka alama yoyote ili kuruhusu kila mtu anayeweza kutumia vipengele vya programu-jalizi kutumia AI. Wasimamizi wanaweza kuitumia kila wakati.','Save limits and permissions'=>'Hifadhi vigezo na ruhusa','Limits and permissions saved.'=>'Vikomo na ruhusa zimehifadhiwa.','The admin screen\'s scripts are missing from this copy of the plugin. Reinstall it from a released package.'=>'Skripti za skrini ya msimamizi hazipo kwenye nakala hii ya programu-jalizi. Isakinishe upya kutoka kwenye kifurushi kilichotolewa.','This screen needs JavaScript.'=>'Skrini hii inahitaji JavaScript.','Languages'=>'Lugha','Upgrade'=>'Boresha','Pricing'=>'Bei','Start Trial'=>'Anza Jaribio','Account'=>'Akaunti','Contact Us'=>'Wasiliana Nasi','Affiliation'=>'Ushirika','the kind of softwarePlugin'=>'Programu-jalizi','greetingHey %s,'=>'Habari %s,','Opt in to get email notifications for security & feature updates, educational content, and occasional offers, and to share some basic WordPress environment info. This will help us make the %s more compatible with your site and better at doing what you need it to.'=>'Jiandikishe kupata arifa za barua pepe kwa ajili ya usalama na masasisho ya vipengele, maudhui ya elimu, na matoleo ya mara kwa mara, na ili kushiriki maelezo ya msingi ya mazingira ya WordPress. Hii itatusaidia kufanya %s iendane zaidi na tovuti yako na iwe bora zaidi katika kufanya kile unachohitaji ifanye.','Opt in to get email notifications for security & feature updates, educational content, and occasional offers, and to share some basic WordPress environment info.'=>'Jiandikishe ili upate arifa za barua pepe kuhusu usalama na masasisho ya vipengele, maudhui ya elimu, na matoleo ya mara kwa mara, na ili kushiriki maelezo fulani ya kimsingi ya mazingira ya WordPress.','If you skip this, that\'s okay! %1$s will still work just fine.'=>'Ukiacha hili, hakuna nchi iliyoharibika! %1$s itaendelea kufanya kazi vizuri tu.','Allow & Continue'=>'Ruhusu na Uendelee','verbSkip'=>'Ruka','Skipping, please wait'=>'Inaruka, tafadhali subiri','Continue'=>'Endelea','Please wait'=>'Tafadhali subiri','as activating pluginActivating'=>'Inafanya kazi','This will allow %s to'=>'Hii itaruhusu %s kuwezesha','Privacy Policy'=>'Sera ya Faragha','Terms of Service'=>'Masharti ya Huduma','License Agreement'=>'Mkataba wa Leseni','Have a license key?'=>'Una ufunguo wa leseni?','Activate License'=>'Washa Leseni','View Basic Profile Info'=>'Tazama Taarifa za Wasifu za Msingi','Your WordPress user\'s: first & last name, and email address'=>'Jina la kwanza na la mwisho, na anwani ya barua pepe ya mtumiaji wako wa WordPress','View Basic Website Info'=>'Onyesha Maelezo ya Msingi ya Tovuti','Homepage URL & title, WP & PHP versions, and site language'=>'URL na kichwa cha ukurasa wa nyumbani, matoleo ya WP na PHP, na lugha ya tovuti','View Basic %s Info'=>'Tazama Taarifa za Msingi za %s','Current %s & SDK versions, and if active or uninstalled'=>'Matoleo ya sasa ya %s & SDK, na ikiwa yanatumika au yameondolewa','Newsletter'=>'Jarida','Updates, announcements, marketing, no spam'=>'Sasisho, matangazo, masoko, hakuna taka data','View Diagnostic Info'=>'Tazama Taarifa za Utambuzi','WordPress & PHP versions, site language & title'=>'Toleo la WordPress na PHP, lugha na kichwa cha tovuti','View Plugins & Themes List'=>'Tazama Orodha ya Programu-jalizi na Mandhari','Names, slugs, versions, and if active or not'=>'Majida, slug, matoleo, na ikiwa ni amilifu au la','optional'=>'si lazima','Never miss an important update'=>'Usikose kamwe sasisho muhimu','We have introduced this opt-in so you never miss an important update and help us make the %s more compatible with your site and better at doing what you need it to.'=>'Tumeleta chaguo hili ili usipate kukosa sasisho muhimu na kutusaidia kufanya %s iendane vyema na tovuti yako na iwe bora zaidi katika kufanya kile unachohitaji ifanye.','Thank you for updating to %1$s v%2$s!'=>'Asante kwa kusasisha hadi %1$s v%2$s!','The prefix must be 1 to 8 lowercase letters or digits, start with a letter, and must not name the plugin.'=>'Kiambishi awali lazima kiwe na herufi 1 hadi 8 ndogo au tarakimu, kianze na herufi, na kisiwe jina la programu-jalizi.','Built by Neil Lock, CEO of Zinn Digital® Ltd'=>'Imetengenezwa na Neil Lock, Mkurugenzi Mtendaji wa Zinn Digital® Ltd','Version %s'=>'Toleo la %s','Page Builder Sandwich website'=>'Tovuti ya Page Builder Sandwich','Zinn Digital® website'=>'Tovuti ya Zinn Digital®','Settings saved.'=>'Mipangilio imehifadhiwa.','See the Pro plans and pricing'=>'Tazama mipango ya Pro na bei','Front-end output'=>'Matokeo ya mbele','Class name prefix'=>'Kiambishi awali cha jina la darasa','Every class name the plugin prints on your pages starts with this prefix, so the pages do not reveal which plugin built them. 1 to 8 lowercase letters or digits, starting with a letter.'=>'Kila jina la darasa ambalo programu-jalizi huchapisha kwenye kurasa zako linaanza na kiambishi hiki, ili kurasa zisifunue ni programu-jalizi ipi iliyozijenga. Herufi ndogo 1 hadi 8 au tarakimu, zinazoanza na herufi moja.','Save'=>'Hifadhi','Beta updates'=>'Sasisho za Beta','This site receives beta versions as updates.'=>'Tovuti hii hupokea matoleo ya beta kama sasisho.','This site receives stable versions only.'=>'Tovuti hii inapokea matoleo thabiti pekee.','Change this on the Account page'=>'Badilisha hii kwenye ukurasa wa Akaunti','Beta versions are offered to licensed Pro installations that are connected to their account. Once connected, you can join from the Account page.'=>'Matoleo ya Beta hutolewa kwa usakinishaji wa Pro wenye leseni ambao umeunganishwa na akaunti yao. Mara baada ya kuunganishwa, unaweza kujiunga kupitia ukurasa wa Akaunti.','Content'=>'Maudhui','Heading'=>'Kichwa cha habari','Text'=>'Maandishi','Style'=>'Mtindo','Plain'=>'Wazi','Accent'=>'Lugha','No languages to switch between. The switcher appears when a translation plugin lists two or more languages.'=>'Hakuna lugha za kubadilisha kati yake. Kitufe cha kubadilisha huonekana wakati plagi ya utafsiri inaorodhesha lugha mbili au zaidi.','Switcher'=>'Kibadilishaji','Accessible label'=>'Lebo inayoweza kufikiwa','Show the current language'=>'Onyesha lugha ya sasa','block titleLanguage switcher (sample)'=>'Kibadilishaji cha lugha (mfano)','block descriptionLists the site\'s languages from the translation plugin, when one is active. It renders nothing otherwise.'=>'Inaorodhesha lugha za tovuti kutoka kwenye plagi-in ya utafsiri, wakati moja ikiwa amilifu. Haionyeshi chochote vinginevyo.','block keywordlanguage'=>'Lugha','block keywordswitcher'=>'kigeuzi','block titleSample content'=>'Maudhui ya mfano','block descriptionA heading and a paragraph, rendered with neutral class names. It is the reference block for the translation contract.'=>'Kichwa cha habari na aya, vilivyotolewa kwa majina ya darasa yasiyoegemea upande wowote. Nikiwa kizuizi cha marejeleo kwa ajili ya mkataba wa tafsiri.','block keywordsample'=>'mfano','block keywordtext'=>'maandishi']];